## Defines the amplitudes for the partials of an additive synthesis note. Since amplitudes add to each#other, the maximum total amplitud is 32767, and there are, at the moment three species, the#maximum amplitude of a note is 10000. If the maximum amp. is exceded, the sound waves will be#truncated in the digital to analogue converter.from random import gammavariatefrom Escalador import escalar_a_rangodef amplitudes(espectro_dist, limit=5000):		amplitudes	= []		for x in espectro_dist:		una_amplitud = gammavariate(.04, 1)	####Play with the beta value when there's							#sound		amplitudes.append(una_amplitud)	amplitudes.sort()	amplitudes.reverse()	amplitudes_escaladas = escalar_a_rango(amplitudes, 10, limit)	return amplitudes_escaladas	